"""Tiny real videos generated by ffmpeg at test time (nothing binary is committed)."""

import os
import subprocess
from dataclasses import dataclass
from pathlib import Path

import pytest


@dataclass(frozen=True)
class Videos:
    with_audio: Path    # 3 s, 1280x720 @ 25 fps, H.264 + AAC 440 Hz tone
    no_audio: Path      # 3 s, 320x240 @ 25 fps, H.264, no audio stream
    corrupt: Path       # mp4 header followed by random bytes


def _ffmpeg(*args: str) -> None:
    subprocess.run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-y", *args], check=True)


@pytest.fixture(scope="session")
def videos(tmp_path_factory) -> Videos:
    root = tmp_path_factory.mktemp("videos")
    with_audio, no_audio, corrupt = root / "with-audio.mp4", root / "no-audio.mp4", root / "corrupt.mp4"
    _ffmpeg(
        "-f", "lavfi", "-i", "testsrc=duration=3:size=1280x720:rate=25",
        "-f", "lavfi", "-i", "sine=frequency=440:duration=3",
        "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest", str(with_audio),
    )
    _ffmpeg("-f", "lavfi", "-i", "testsrc=duration=3:size=320x240:rate=25", "-c:v", "libx264", "-pix_fmt", "yuv420p", str(no_audio))
    corrupt.write_bytes(b"\x00\x00\x00\x18ftypisom" + os.urandom(64 * 1024))
    return Videos(with_audio, no_audio, corrupt)
